  return spawnSync('git', ['-C', lane, ...a], { maxBuffer: 64 << 20 });
}

edits.new:
function git(lane, a) {
  if (a[0] === 'show') {
    const p = join(lane, String(a[1]).slice(41));
    if (existsSync(p)) return { status: 0, stdout: readFileSync(p) };
    return { status: 1, stdout: null };
  }
  return spawnSync('git', ['-C', lane, ...a], { maxBuffer: 64 << 20 });
}
